import{f as a,c as n,o as s,ah as l}from"./chunks/framework.5bt9HFMa.js";const u=JSON.parse('{"title":"操作系统调度的机制","description":"两级调度、抢占性与多级反馈队列的解析","frontmatter":{"title":"操作系统调度的机制","date":"2025-11-03T00:00:00.000Z","tags":["操作系统","调度算法","CPU调度"],"description":"两级调度、抢占性与多级反馈队列的解析","author":"沃以","publish":true},"headers":[],"relativePath":"posts/操作系统调度的机制.md","filePath":"posts/操作系统调度的机制.md","lastUpdated":1764000969000}'),r={name:"posts/操作系统调度的机制.md"};function o(e,t,d,i,h,p){return s(),n("div",null,t[0]||(t[0]=[l(`<h1 id="操作系统调度的机制" tabindex="-1">操作系统调度的机制 <a class="header-anchor" href="#操作系统调度的机制" aria-label="Permalink to &quot;操作系统调度的机制&quot;">​</a></h1><p>🎬 <strong>一个小故事</strong></p><p>想象你是一家咖啡馆的老板，每天顾客源源不断。有时候一个顾客点的是复杂的定制饮品（长作业），有时候只是要一杯黑咖啡（短作业）。关键问题来了：</p><ul><li>你是按照先到先服务的顺序？还是先做简单的，后做复杂的？</li><li>一个 VIP 顾客来了，你是否中断当前的工作去服务他？</li><li>如果总是有新的急客到来，那些耐心的慢客是否永远得不到服务？</li></ul><p>操作系统的调度算法，就是这家咖啡馆的&quot;工作流程&quot;。</p><blockquote><p><strong>Tips</strong>：这里假设咖啡馆只有<strong>一位咖啡师</strong>（即单核 CPU）来讨论调度问题。现代多核处理器会并行运行多个进程，但核心的调度思想是相同的——每个核心都需要独立做出&quot;谁先服务&quot;的决策。所以这里的所有讨论都适用于多核系统中的<strong>每一个核心</strong>。</p></blockquote><hr><h2 id="_1-调度的层级结构" tabindex="-1">1. 调度的层级结构 <a class="header-anchor" href="#_1-调度的层级结构" aria-label="Permalink to &quot;1. 调度的层级结构&quot;">​</a></h2><p>操作系统调度分为两个关键层级：</p><pre class="mermaid mermaid-3">graph LR
    A[外存作业池] --&gt;|作业调度| B[内存]
    B --&gt;|进程调度| C[CPU]
    style A fill:#e1f5fe,stroke:#0288d1
    style B fill:#e8f5e9,stroke:#2e7d32
    style C fill:#ffe0b2,stroke:#ef6c00</pre><ul><li><strong>作业调度</strong>：决定哪些作业可以进入内存（准入控制）</li><li><strong>进程调度</strong>：决定内存中的哪个作业使用 CPU（执行控制）</li></ul><blockquote><p>💡 <strong>作业管理方式</strong>：</p><ul><li><strong>单道系统</strong>：内存只能容纳 1 个作业，简单但低效</li><li><strong>两道系统</strong>：内存最多容纳 2 个作业，本文以此为例</li><li><strong>多道系统</strong>：内存容纳多个作业，现代操作系统的标准配置</li></ul></blockquote><hr><h2 id="_2-两级调度-分工明确" tabindex="-1">2. 两级调度：分工明确 <a class="header-anchor" href="#_2-两级调度-分工明确" aria-label="Permalink to &quot;2. 两级调度：分工明确&quot;">​</a></h2><h3 id="_2-1-作业调度-看-时间-——-短作业优先-sjf" tabindex="-1">2.1 作业调度：看“时间” —— 短作业优先（SJF） <a class="header-anchor" href="#_2-1-作业调度-看-时间-——-短作业优先-sjf" aria-label="Permalink to &quot;2.1 作业调度：看“时间” —— 短作业优先（SJF）&quot;">​</a></h3><ul><li><strong>目标</strong>：提高系统整体效率</li><li><strong>规则</strong>：在等待进入内存的作业中，选择<strong>估计运行时间最短</strong>的</li><li><strong>特点</strong>：<strong>非抢占式</strong> —— 一旦进入内存，就不会被踢出去</li></ul><h3 id="_2-2-进程调度-看-权重-——-抢占式优先级调度" tabindex="-1">2.2 进程调度：看&quot;权重&quot; —— 抢占式优先级调度 <a class="header-anchor" href="#_2-2-进程调度-看-权重-——-抢占式优先级调度" aria-label="Permalink to &quot;2.2 进程调度：看&quot;权重&quot; —— 抢占式优先级调度&quot;">​</a></h3><ul><li><strong>目标</strong>：保证重要任务优先执行</li><li><strong>规则</strong>：采用<strong>优先级编号系统</strong>，优先级数值越小优先级越高（如：优先级 1 &gt; 优先级 2 &gt; 优先级 3）</li><li><strong>特点</strong>：<strong>抢占式</strong> —— 高优先级作业进入内存后，可以立即打断正在运行的低优先级作业</li></ul><blockquote><p>💡 <strong>注</strong>：不同系统可能采用不同的优先级定义（有些系统优先级数值越大优先级越高），本文统一采用&quot;数值越小优先级越高&quot;的标准定义</p></blockquote><h3 id="_2-3-协同工作流程" tabindex="-1">2.3 协同工作流程 <a class="header-anchor" href="#_2-3-协同工作流程" aria-label="Permalink to &quot;2.3 协同工作流程&quot;">​</a></h3><pre class="mermaid mermaid-4">flowchart TD
    Start[新作业到达] --&gt; CheckMem{内存是否满?}
    CheckMem -- 否 --&gt; JobSched[作业调度: 从等待队列选SJF进内存]
    JobSched --&gt; ProcSched[进程调度: 选最高优先级作业运行]
    CheckMem -- 是 --&gt; Wait[作业加入等待队列]
    Wait --&gt;|内存有空位| JobSched
    ProcSched --&gt; Run[作业运行]
    Run --&gt; Complete{作业完成?}
    Complete -- 是 --&gt; Release[释放内存]
    Release --&gt; CheckMem
    Complete -- 否 --&gt; Preempt{有更高优先级作业进入?}
    Preempt -- 是 --&gt; ProcSched
    Preempt -- 否 --&gt; Run</pre><blockquote><p>💡 <strong>关键点</strong>：作业调度遵循**短作业优先（SJF）**原则，每次选择等待队列中估计运行时间最短的作业进入内存</p></blockquote><hr><h2 id="_3-抢占式-vs-非抢占式-直观对比" tabindex="-1">3. 抢占式 vs 非抢占式：直观对比 <a class="header-anchor" href="#_3-抢占式-vs-非抢占式-直观对比" aria-label="Permalink to &quot;3. 抢占式 vs 非抢占式：直观对比&quot;">​</a></h2><h3 id="_3-1-场景设定" tabindex="-1">3.1 场景设定 <a class="header-anchor" href="#_3-1-场景设定" aria-label="Permalink to &quot;3.1 场景设定&quot;">​</a></h3><ul><li><strong>进程 A</strong>：低优先级，需要运行 10 个时间单位</li><li><strong>进程 B</strong>：高优先级，在时间 2 到达，需要运行 5 个时间单位</li></ul><h3 id="_3-2-非抢占式调度" tabindex="-1">3.2 非抢占式调度 <a class="header-anchor" href="#_3-2-非抢占式调度" aria-label="Permalink to &quot;3.2 非抢占式调度&quot;">​</a></h3><p>在这种模式下，一旦 A 开始运行，B 必须等待 A 完全结束：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间轴：0         10        15</span></span>
<span class="line"><span>        |----------|---------|</span></span>
<span class="line"><span>        |    A     |    B    |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>进程到达：A(t=0)      B到达(t=2)但无法抢占</span></span></code></pre></div><ul><li>A 从 0 运行到 10</li><li>B 在 t=2 到达，但由于 A 正在运行且系统不支持抢占，B 必须等待</li><li>B 从 10 开始运行，15 结束</li><li><strong>B 的等待时间 = 10 - 2 = 8 个时间单位</strong></li></ul><h3 id="_3-3-抢占式调度" tabindex="-1">3.3 抢占式调度 <a class="header-anchor" href="#_3-3-抢占式调度" aria-label="Permalink to &quot;3.3 抢占式调度&quot;">​</a></h3><p>在这种模式下，B 到达后立即获得 CPU，打断 A 的执行：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间轴：0    2         7        15</span></span>
<span class="line"><span>        |----|---------|---------|</span></span>
<span class="line"><span>        | A1 |    B    |   A2    |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>             ↑ t=2时刻，B到达，立即抢占</span></span></code></pre></div><ul><li>A 从 0 运行到 2（被 B 打断 = <strong>抢占点</strong>）</li><li>B 从 2 运行到 7（立即执行，几乎无等待）</li><li>A 从 7 继续运行到 15（完成剩余 8 个单位）</li><li><strong>B 的等待时间 ≈ 0</strong>（只需排队极短时间）</li></ul><p><strong>对比效果</strong>：抢占式调度使 B 的响应延迟从 8 个时间单位降低到接近 0</p><h3 id="_3-4-关键差异总结" tabindex="-1">3.4 关键差异总结 <a class="header-anchor" href="#_3-4-关键差异总结" aria-label="Permalink to &quot;3.4 关键差异总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方面</th><th>非抢占式</th><th>抢占式</th></tr></thead><tbody><tr><td><strong>响应性</strong></td><td>差（重要任务需等待）</td><td>好（重要任务立即执行）</td></tr><tr><td><strong>实现复杂度</strong></td><td>简单</td><td>复杂（需保存/恢复进程状态）</td></tr><tr><td><strong>适用场景</strong></td><td>批处理系统</td><td>交互式/实时系统</td></tr></tbody></table><hr><h2 id="_4-多级反馈队列调度-mlfq" tabindex="-1">4. 多级反馈队列调度（MLFQ） <a class="header-anchor" href="#_4-多级反馈队列调度-mlfq" aria-label="Permalink to &quot;4. 多级反馈队列调度（MLFQ）&quot;">​</a></h2><h3 id="_4-1-为什么需要-mlfq" tabindex="-1">4.1 为什么需要 MLFQ？ <a class="header-anchor" href="#_4-1-为什么需要-mlfq" aria-label="Permalink to &quot;4.1 为什么需要 MLFQ？&quot;">​</a></h3><ul><li>现实中很难预知进程运行时间（SJF 的前提）</li><li>需要自动区分不同类型的进程</li><li>要同时兼顾短作业的响应性和长作业的完成</li></ul><h3 id="_4-2-三级队列典型配置" tabindex="-1">4.2 三级队列典型配置 <a class="header-anchor" href="#_4-2-三级队列典型配置" aria-label="Permalink to &quot;4.2 三级队列典型配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>队列</th><th>优先级</th><th>时间片大小</th><th>适合的进程类型</th></tr></thead><tbody><tr><td><strong>Q1</strong></td><td>最高</td><td>4</td><td>短作业、交互式进程</td></tr><tr><td><strong>Q2</strong></td><td>中等</td><td>8</td><td>中等长度作业</td></tr><tr><td><strong>Q3</strong></td><td>最低</td><td>16</td><td>长作业、CPU密集型进程</td></tr></tbody></table><h3 id="_4-3-调度规则与核心机制" tabindex="-1">4.3 调度规则与核心机制 <a class="header-anchor" href="#_4-3-调度规则与核心机制" aria-label="Permalink to &quot;4.3 调度规则与核心机制&quot;">​</a></h3><h4 id="基本规则" tabindex="-1">基本规则 <a class="header-anchor" href="#基本规则" aria-label="Permalink to &quot;基本规则&quot;">​</a></h4><ol><li><strong>新进程</strong>总是从 <strong>Q1</strong> 开始</li><li>如果在时间片内<strong>完成</strong>，进程结束</li><li>如果时间片用完但<strong>未完成</strong>，降级到下一级队列</li><li>如果因为<strong>I/O 等待</strong>而放弃 CPU，保持在当前队列（不降级）</li><li>CPU 总是优先运行<strong>最高优先级非空队列</strong>中的进程</li></ol><h4 id="防止饥饿-老化机制-aging-等待时间补偿-✨" tabindex="-1">防止饥饿：老化机制（Aging - 等待时间补偿）✨ <a class="header-anchor" href="#防止饥饿-老化机制-aging-等待时间补偿-✨" aria-label="Permalink to &quot;防止饥饿：老化机制（Aging - 等待时间补偿）✨&quot;">​</a></h4><p>标准 MLFQ 必须配备的关键机制，否则会导致严重的进程饥饿：</p><ul><li><strong>问题</strong>：持续有新的短作业到达时，Q3 中的长作业可能永远得不到执行</li><li><strong>解决方案</strong>：每隔一段时间（如 100ms），将所有等待时间过长的进程提升到更高优先级队列</li><li><strong>规则</strong>： <ul><li>等待 100ms 在 Q2 → 提升到 Q1</li><li>等待 100ms 在 Q3 → 提升到 Q2</li></ul></li><li><strong>参数范围</strong>： <ul><li>短期系统（响应式）：50-100ms</li><li>一般交互系统：100-200ms</li><li>批处理系统：可达 1-5s</li></ul></li><li><strong>效果</strong>：保证即使是长作业也最终能获得执行机会</li><li><strong>原理</strong>：进程&quot;变老&quot;（等待时间增加）后，获得更高的优先级，避免被永久饿死</li></ul><blockquote><p>💡 <strong>本文简化</strong>：后续示例采用简化版 MLFQ（不涉及老化机制）演示基本流程，实际系统中必须配备老化机制</p></blockquote><h3 id="_4-4-调度流程图" tabindex="-1">4.4 调度流程图 <a class="header-anchor" href="#_4-4-调度流程图" aria-label="Permalink to &quot;4.4 调度流程图&quot;">​</a></h3><pre class="mermaid mermaid-5">flowchart TD
    New[新进程] --&gt; Q1[进入Q1队列]
    Q1 --&gt; Run1[运行4单位]
    Run1 --&gt;|完成| End[结束]
    Run1 --&gt;|未完成| Q2[降级到Q2队列]
    Q2 --&gt; Run2[运行8单位]
    Run2 --&gt;|完成| End
    Run2 --&gt;|未完成| Q3[降级到Q3队列]
    Q3 --&gt; Run3[在Q3中运行<br>每个时间片16单位]
    Run3 --&gt;|完成| End
    Run3 --&gt;|时间片用完<br>未完成| Q3
    Run1 --&gt;|I/O等待| Q1[保持在Q1<br>等待I/O完成后继续]
    Run2 --&gt;|I/O等待| Q2[保持在Q2<br>等待I/O完成后继续]
    Run3 --&gt;|I/O等待| Q3[保持在Q3<br>等待I/O完成后继续]</pre><blockquote><p>💡 <strong>Q3 特性</strong>：进程在 Q3 中采用轮转调度，每次运行 16 个时间单位，若未完成则继续排队等待下一个时间片</p></blockquote><h3 id="_4-5-实际执行示例" tabindex="-1">4.5 实际执行示例 <a class="header-anchor" href="#_4-5-实际执行示例" aria-label="Permalink to &quot;4.5 实际执行示例&quot;">​</a></h3><h4 id="示例场景设定" tabindex="-1">示例场景设定 <a class="header-anchor" href="#示例场景设定" aria-label="Permalink to &quot;示例场景设定&quot;">​</a></h4><p>三个进程同时到达（t=0）：</p><ul><li><strong>P1</strong>（6单位）：Q1 运行 4 单位 → 降级到 Q2 → 再运行 2 单位完成</li><li><strong>P2</strong>（13单位）：Q1 运行 4 单位 → 降级到 Q2 → 运行 8 单位 → 降级到 Q3 → 运行 1 单位完成</li><li><strong>P3</strong>（10单位）：Q1 运行 4 单位 → 降级到 Q2 → 在 Q2 中运行 6 单位完成</li></ul><h4 id="详细执行时间轴" tabindex="-1">详细执行时间轴 <a class="header-anchor" href="#详细执行时间轴" aria-label="Permalink to &quot;详细执行时间轴&quot;">​</a></h4><table tabindex="0"><thead><tr><th>时间</th><th>Q1队列</th><th>Q2队列</th><th>Q3队列</th><th>CPU执行</th><th>备注</th></tr></thead><tbody><tr><td>0-4</td><td>P2,P3等待</td><td>-</td><td>-</td><td>P1运行</td><td>P1在Q1执行4单位</td></tr><tr><td>4-8</td><td>P3等待</td><td>P1等待</td><td>-</td><td>P2运行</td><td>P2在Q1执行4单位</td></tr><tr><td>8-12</td><td>-</td><td>P1,P3等待</td><td>-</td><td>P3运行</td><td>P3在Q1执行4单位</td></tr><tr><td>12-16</td><td>-</td><td>P1,P3运行</td><td>-</td><td>P1运行</td><td>P1在Q2执行2单位→<strong>完成</strong></td></tr><tr><td>16-20</td><td>-</td><td>P3运行</td><td>-</td><td>P3运行</td><td>P3在Q2执行4单位</td></tr><tr><td>20-24</td><td>-</td><td>P2等待</td><td>P2,P3等待</td><td>P3运行</td><td>P3在Q2执行2单位→<strong>完成</strong></td></tr><tr><td>24-32</td><td>-</td><td>-</td><td>P2运行</td><td>P2运行</td><td>P2在Q3执行8单位</td></tr><tr><td>32-33</td><td>-</td><td>-</td><td>-</td><td>P2运行</td><td>P2在Q3执行1单位→<strong>完成</strong></td></tr></tbody></table><h4 id="性能指标" tabindex="-1">性能指标 <a class="header-anchor" href="#性能指标" aria-label="Permalink to &quot;性能指标&quot;">​</a></h4><table tabindex="0"><thead><tr><th>进程</th><th>开始时间</th><th>结束时间</th><th>等待时间</th><th>周转时间</th></tr></thead><tbody><tr><td>P1</td><td>0</td><td>12</td><td>6</td><td>12</td></tr><tr><td>P2</td><td>0</td><td>33</td><td>20</td><td>33</td></tr><tr><td>P3</td><td>0</td><td>24</td><td>14</td><td>24</td></tr><tr><td><strong>平均</strong></td><td>-</td><td>-</td><td><strong>13.3</strong></td><td><strong>23</strong></td></tr></tbody></table><p><strong>计算说明</strong>：</p><ul><li><strong>等待时间</strong> = 进程首次运行前的等待时间 + 被打断后重新等待的总时间 <ul><li>P1：0-0（未等待）+ 8-12（等待2单位） + 12-16（等待2单位） = 6 单位</li><li>P2：0-2（等待2单位） + 8-24（等待16单位） + 24-32（等待2单位） = 20 单位</li><li>P3：0-8（等待8单位）+ 12-16（等待4单位） = 14 单位</li></ul></li><li><strong>周转时间</strong> = 结束时间 - 开始时间 <ul><li>P1：12 - 0 = 12 单位</li><li>P2：33 - 0 = 33 单位</li><li>P3：24 - 0 = 24 单位</li></ul></li><li><strong>平均值</strong>：(6+20+14)/3 = 13.3；(12+33+24)/3 = 23</li></ul><blockquote><p>💡 <strong>观察</strong>：短进程（P1）获得快速完成，长进程（P2）虽然等待长，但不会被无限延迟（在 Q3 最终获得执行）</p></blockquote><hr><h2 id="_5-三种调度模型综合评估" tabindex="-1">5. 三种调度模型综合评估 <a class="header-anchor" href="#_5-三种调度模型综合评估" aria-label="Permalink to &quot;5. 三种调度模型综合评估&quot;">​</a></h2><p>现在我们已经理解了三种主要的调度算法：</p><ul><li><strong>两级调度</strong>（作业调度用 SJF，进程调度用优先级）</li><li><strong>多级反馈队列</strong>（MLFQ）</li><li><strong>纯 SJF</strong>（纯短作业优先）</li></ul><p>以下通过详细的对比，帮助您理解各算法的适用场景和权衡。</p><h3 id="_5-1-三种调度模型对比" tabindex="-1">5.1 三种调度模型对比 <a class="header-anchor" href="#_5-1-三种调度模型对比" aria-label="Permalink to &quot;5.1 三种调度模型对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>两级调度（SJF+优先级）</th><th>多级反馈队列（MLFQ）</th><th>纯SJF（非抢占）</th></tr></thead><tbody><tr><td><strong>是否需要预知运行时间</strong></td><td>是</td><td>否</td><td>是</td></tr><tr><td><strong>是否支持抢占</strong></td><td>进程调度层支持</td><td>完全支持</td><td>不支持</td></tr><tr><td><strong>防止饥饿机制</strong></td><td>依赖作业调度策略</td><td>需要老化机制</td><td>无法防止</td></tr><tr><td><strong>内存管理</strong></td><td>限制并发作业数</td><td>通常不限制</td><td>通常不限制</td></tr><tr><td><strong>主要优势</strong></td><td>简单明确，效率高</td><td>自适应，兼顾各类进程</td><td>理论最优平均等待时间</td></tr><tr><td><strong>主要缺点</strong></td><td>需要预知时间，可能导致进程饥饿</td><td>实现复杂，参数配置困难</td><td>需要预知时间，无抢占导致响应慢</td></tr><tr><td><strong>适用场景</strong></td><td>批处理系统、时间预知清楚</td><td>通用操作系统、交互式系统</td><td>学术研究、理论分析</td></tr></tbody></table><p><strong>解读</strong>：</p><ul><li><strong>两级调度</strong>是传统批处理系统的选择，简单高效</li><li><strong>MLFQ</strong> 是现代通用操作系统（Unix、Linux）的常用方案，平衡了各类进程的需求</li><li><strong>纯SJF</strong> 主要用于理论计算，实际系统很少采用</li></ul><hr><h3 id="_5-2-饥饿问题的深入分析" tabindex="-1">5.2 饥饿问题的深入分析 <a class="header-anchor" href="#_5-2-饥饿问题的深入分析" aria-label="Permalink to &quot;5.2 饥饿问题的深入分析&quot;">​</a></h3><h4 id="什么是进程饥饿-starvation" tabindex="-1">什么是进程饥饿（Starvation）？ <a class="header-anchor" href="#什么是进程饥饿-starvation" aria-label="Permalink to &quot;什么是进程饥饿（Starvation）？&quot;">​</a></h4><p><strong>定义</strong>：一个就绪的进程长时间得不到 CPU 时间，无限期地等待执行的现象。</p><h4 id="各调度算法的饥饿风险" tabindex="-1">各调度算法的饥饿风险 <a class="header-anchor" href="#各调度算法的饥饿风险" aria-label="Permalink to &quot;各调度算法的饥饿风险&quot;">​</a></h4><h5 id="两级调度-sjf-优先级-中的饥饿" tabindex="-1">两级调度（SJF + 优先级）中的饥饿 <a class="header-anchor" href="#两级调度-sjf-优先级-中的饥饿" aria-label="Permalink to &quot;两级调度（SJF + 优先级）中的饥饿&quot;">​</a></h5><p><strong>风险场景</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景：不断有新的短作业到达系统</span></span>
<span class="line"><span>- 长作业 L：需要 1 小时运行时间</span></span>
<span class="line"><span>- 短作业流 S1, S2, S3...：每个 1 分钟</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SJF 作业调度的选择过程：</span></span>
<span class="line"><span>时间 0-1分钟：选 S1 进内存执行</span></span>
<span class="line"><span>时间 1-2分钟：选 S2 进内存执行</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>问题：长作业 L 可能永远被推后！</span></span></code></pre></div><p><strong>防止机制</strong>：</p><ul><li>设置最大等待时间阈值，超过则强制进入内存</li><li>采用&quot;年龄&quot;概念：等待时间越长，优先级越高</li></ul><h5 id="多级反馈队列-mlfq-中的饥饿" tabindex="-1">多级反馈队列（MLFQ）中的饥饿 <a class="header-anchor" href="#多级反馈队列-mlfq-中的饥饿" aria-label="Permalink to &quot;多级反馈队列（MLFQ）中的饥饿&quot;">​</a></h5><p><strong>风险场景</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景：持续有高优先级（交互式）进程到达</span></span>
<span class="line"><span>- 长作业进程在 Q3，但频繁有新进程进 Q1</span></span>
<span class="line"><span>- Q1 和 Q2 总是有进程等待执行</span></span>
<span class="line"><span>- Q3 中的长作业永远得不到 CPU</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这就是 MLFQ 必须配备&quot;老化机制&quot;的原因！</span></span></code></pre></div><p><strong>防止机制</strong>：</p><ul><li><strong>老化机制</strong>：每隔一定时间，所有等待过久的进程自动提升到更高优先级队列</li><li>典型参数：等待 100ms 以上自动提升一级</li></ul><h4 id="纯-sjf-非抢占-中的饥饿" tabindex="-1">纯 SJF（非抢占）中的饥饿 <a class="header-anchor" href="#纯-sjf-非抢占-中的饥饿" aria-label="Permalink to &quot;纯 SJF（非抢占）中的饥饿&quot;">​</a></h4><p><strong>风险等级</strong>：⚠️ <strong>最严重</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景：有两个进程</span></span>
<span class="line"><span>- 长进程 L：10 个时间单位（首先到达）</span></span>
<span class="line"><span>- 短进程 S：1 个时间单位（后到达）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>执行顺序：</span></span>
<span class="line"><span>- L 运行 10 个时间单位</span></span>
<span class="line"><span>- 最后 S 才能运行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果源源不断有新短进程到达，L 会被无限延迟！</span></span></code></pre></div><p><strong>无法有效防止</strong>的原因：</p><ul><li>非抢占特性决定了一旦进程开始运行就不会被中断</li><li>没有优先级机制可以打断长进程</li></ul><h3 id="总结表" tabindex="-1">总结表 <a class="header-anchor" href="#总结表" aria-label="Permalink to &quot;总结表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>饥饿风险</th><th>防止方案</th></tr></thead><tbody><tr><td><strong>两级调度</strong></td><td>中等</td><td>最大等待时间、年龄机制</td></tr><tr><td><strong>MLFQ</strong></td><td>低（配老化机制）</td><td><strong>必需老化机制</strong>否则高风险</td></tr><tr><td><strong>纯SJF</strong></td><td>很高</td><td>改用抢占式 SJF 或其他算法</td></tr></tbody></table><hr><h2 id="_6-实战应用场景" tabindex="-1">6. 实战应用场景 <a class="header-anchor" href="#_6-实战应用场景" aria-label="Permalink to &quot;6. 实战应用场景&quot;">​</a></h2><h3 id="现代操作系统的实际选择" tabindex="-1">现代操作系统的实际选择 <a class="header-anchor" href="#现代操作系统的实际选择" aria-label="Permalink to &quot;现代操作系统的实际选择&quot;">​</a></h3><p>了解了三种算法的特点后，让我们看看真实的操作系统是如何选择的：</p><h4 id="linux-unix-系统-mlfq-变体-cfs-✨" tabindex="-1">Linux/Unix 系统：MLFQ 变体（CFS）✨ <a class="header-anchor" href="#linux-unix-系统-mlfq-变体-cfs-✨" aria-label="Permalink to &quot;Linux/Unix 系统：MLFQ 变体（CFS）✨&quot;">​</a></h4><p><strong>采用算法</strong>：完全公平调度器（Completely Fair Scheduler, CFS）</p><ul><li><strong>基础</strong>：多级队列的思想</li><li><strong>特色</strong>：使用红黑树代替固定队列，动态调整优先级</li><li><strong>老化机制</strong>：完整实现，防止任何进程长期饥饿</li><li><strong>适配性</strong>：自动识别 I/O 密集型 vs CPU 密集型进程</li></ul><p><strong>典型场景</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 文本编辑器：高优先级，快速响应用户输入</span></span>
<span class="line"><span>- 后台下载：低优先级，不影响前台任务</span></span>
<span class="line"><span>- 数据库：中等优先级，平衡吞吐和响应</span></span></code></pre></div><h4 id="实时操作系统-rtos-两级调度" tabindex="-1">实时操作系统（RTOS）：两级调度 <a class="header-anchor" href="#实时操作系统-rtos-两级调度" aria-label="Permalink to &quot;实时操作系统（RTOS）：两级调度&quot;">​</a></h4><p><strong>采用算法</strong>：优先级 + SJF 变体</p><ul><li><strong>特点</strong>：预测性强，行为可预测</li><li><strong>保证</strong>：不同优先级任务的响应时间有上界</li><li><strong>应用</strong>：航空航天、医疗设备、工业控制</li></ul><h4 id="批处理系统-大数据处理-优化的-sjf" tabindex="-1">批处理系统（大数据处理）：优化的 SJF <a class="header-anchor" href="#批处理系统-大数据处理-优化的-sjf" aria-label="Permalink to &quot;批处理系统（大数据处理）：优化的 SJF&quot;">​</a></h4><p><strong>采用算法</strong>：带老化机制的 SJF</p><ul><li><strong>目标</strong>：最大化系统吞吐量</li><li><strong>特点</strong>：长作业最终必定执行</li><li><strong>应用</strong>：Hadoop、Spark 等分布式计算框架</li></ul><hr><h2 id="_7-关键要点总结" tabindex="-1">7. 关键要点总结 <a class="header-anchor" href="#_7-关键要点总结" aria-label="Permalink to &quot;7. 关键要点总结&quot;">​</a></h2><ul><li><strong>两级调度</strong>：准入看效率（运行时间），执行看重要性（优先级）</li><li><strong>抢占性</strong>：决定了高优先级任务能否&quot;插队&quot;，直接影响系统响应性</li><li><strong>多级反馈队列</strong>：通过多级试探自动分类进程，是 SJF 思想的实用化实现</li><li><strong>I/O密集型进程</strong>：在 MLFQ 中天然获得高响应性（频繁阻塞不降级）</li><li><strong>老化机制</strong>：是现代调度系统防止饥饿的必要机制</li><li><strong>设计哲学</strong>：调度的本质是在<strong>系统效率</strong>与<strong>用户体验</strong>之间找到最佳平衡点</li></ul>`,113)]))}const c=a(r,[["render",o]]);export{u as __pageData,c as default};
